WITH recent_customers AS (SELECT *, CONCAT_WS('/', name, segment) AS name_segment_key FROM customers WHERE segment = 'Consumer' AND is_active = TRUE AND signup_date <= '2023-12-27'), agg AS (SELECT is_active, SUM(CASE WHEN country = 'UK' THEN age ELSE 0 END) AS uk_age, AVG(credit_limit) AS avg_credit_limit FROM recent_customers GROUP BY is_active) SELECT is_active, avg_credit_limit FROM agg WHERE uk_age > 57;
